#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int current = 0; // start at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target_long = strtol(argv[i], &endptr, 10);
        int target = (int)target_long;
        // Validate floor range 0..9 inclusive
        if (target_long < 0 || target_long > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        // Move elevator until it reaches the target floor
        while (current != target) {
            if (current < target) {
                int next = current + 1;
                printf("MOVE_UP %d->%d\n", current, next);
                current = next;
            } else {
                int next = current - 1;
                printf("MOVE_DOWN %d->%d\n", current, next);
                current = next;
            }
        }
        // Arrival actions
        printf("ARRIVE %d\n", current);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current);
    return 0;
}
